result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "interaction_checker.py", "content": """"Interaction checker over an invented (fully fictional) drug-class table.

Pharmacy-informatics course software. All substances are invented.
"""

# --- Drug table ---------------------------------------------------------

DRUG_CLASSES = {
    "examplecillin": "BETALIKE",
    "demykillin": None,  # placeholder removed below
}
DRUG_CLASSES = {
    "examplecillin": "BETALIKE",
    "demykillin": "BETALIKE",
}

DRUG_CLASSES = {
    "examplecillin": "BETALIKE",
    "demykillin": "BETALIKE",
    "sleepatol": "SEDAKIND",
    "dozerol": "SEDAKIND",
    "wakeamine": "STIMUKIND",
    "thinnerol": "COAGULIKE",
}


def known_drugs():
    """Sorted list of all known drug names."""
    return sorted(DRUG_CLASSES)


# --- Interaction rules --------------------------------------------------

CLASS_RULES = {
    frozenset(["SEDAKIND", "SEDAKIND"]): ("major", "duplicate therapy"),
    frozenset(["SEDAKIND", "STIMUKIND"]): ("moderate", None),
    frozenset(["COAGULIKE", "BETALIKE"]): ("minor", None),
}

# Drug-level overrides win over class-level rules.
DRUG_RULES = {
    frozenset(["sleepatol", "wakeamine"]): ("major",),
}


def _normalize(med_list):
    names = [m.strip().lower() for m in med_list]
    unknown = sorted(set(names) - set(DRUG_CLASSES))
    if unknown:
        raise ValueError(
            f"unknown drug(s): {', '.join(unknown)}; "
            f"known drugs: {', '.join(known_drugs())}"
        )
    return names


def check(med_list):
    """Return a deduplicated list of interaction findings for med_list.

    Each finding is a dict:
      {"pair": tuple(sorted pair), "severity": str, "source": "class"|"drug"}
    Pairs are order-insensitive; findings are unique per unordered pair.
    """
    names = _normalize(list(med_list))

    findings = {}
    for i in range(len(names)):
        for j in range(i + 1, len(names)):
            a, b = names[i], names[j]
            if a == b:
                continue
            pair = frozenset([a, b])
            key = tuple(sorted(pair))

            if pair in DRUG_RULES:
                severity, source = DRUG_RULES[pair][0], "drug"
            else:
                ca, cb = DRUG_CLASSES[a], DRUG_CLASSES[b]
                rule = CLASS_RULES.get(frozenset([ca, cb]))
                if rule is None:
                    continue
                severity, source = rule[0], "class"

            # Deduplicate: keep the first finding per unordered pair.
            # A drug-level finding always beats a class-level one.
            existing = findings.get(key)
            if existing is None or (
                existing["source"] == "class" and source == "drug"
            ):
                findings[key] = {
                    "pair": key,
                    "severity": severity,
                    "source": source,
                }

    return list(findings.values())
